const ids=['bill','people','tip'];
const el={};for(const i of ids.concat(['err','rTip','rTotal','rEach']))el[i]=document.getElementById(i);
function fmt(n){return n.toFixed(2)}
function calc(){
const b=parseFloat(el.bill.value),p=parseInt(el.people.value,10),t=parseFloat(el.tip.value);
let msg='';
if(!(b>=0))msg='Enter the bill amount as a number, 0 or more.';
else if(!(p>=1))msg='Enter at least 1 person.';
else if(!(t>=0))msg='Enter the tip as a number, 0 or more.';
el.err.textContent=msg;
if(msg){el.rTip.textContent=el.rTotal.textContent=el.rEach.textContent='–';return}
const tip=b*t/100,tot=b+tip;
el.rTip.textContent=fmt(tip);el.rTotal.textContent=fmt(tot);el.rEach.textContent=fmt(tot/p);
}
for(const i of ids)el[i].addEventListener('input',calc);
calc();

