const bill=document.getElementById('bill');
const people=document.getElementById('people');
const tipIn=document.getElementById('tip');
const roundUp=document.getElementById('roundUp');
const err=document.getElementById('err');
const rTip=document.getElementById('rTip');
const rTotal=document.getElementById('rTotal');
const rEach=document.getElementById('rEach');
function fmt(n){return n.toFixed(2)}
function calc(){
const b=parseFloat(bill.value),p=parseInt(people.value,10),t=parseFloat(tipIn.value);
let msg='';
if(!(b>=0))msg='Enter the bill amount as a number, 0 or more.';
else if(!(p>=1))msg='Enter at least 1 person.';
else if(!(t>=0))msg='Enter the tip as a number, 0 or more.';
err.textContent=msg;
if(msg){rTip.textContent='–';rTotal.textContent='–';rEach.textContent='–';return}
const tip=b*t/100,tot=b+tip;
let each=tot/p;
if(roundUp.checked)each=Math.ceil(Math.round(each*100)/100);
rTip.textContent=fmt(tip);rTotal.textContent=fmt(tot);rEach.textContent=fmt(each);
}
for(const inp of [bill,people,tipIn])inp.addEventListener('input',calc);
roundUp.addEventListener('change',calc);
calc();
